\begin{proof}
We begin by defining the set:
\begin{equation}
    X=\lrs{x\in \F_2^{2n}:2^np_{\psi}(x)\geq \frac{\gamma}{4}}.
\end{equation}
We prove that this set is large, and then construct $S$ as a random subset of $X$. 
It is clear that $\f{\gamma}{4}\abs*{X}\le \sum_{x\in X}2^np_\psi(x)\le \sum_{x\in \Fnn}2^np_\psi(x) = 2^n$. This implies that $\abs*{X}\le \f{4}{\gamma}2^n$.
Furthermore, we can lower bound $|X|$ using Markov's inequality:
\begin{equation}
  \gamma 
    \leq \E_{x\sim q_\psi}\lrb{2^np_{\psi}(x)}
    \leq \PP_{x\sim q_\psi}\lrb{2^np_\psi(x)\geq \f{\gamma}{4}}+\f{\gamma}{4}.
\end{equation}
Since $q_{\psi}(x)\leq 2^{-n}$ for all $x$, we have
\begin{equation}
  \PP_{x\sim q_\psi}\lrb{2^np_\psi(x) 
    \geq \f{\gamma}{4}}
    = \sum_{x\in X}q_{\psi}(x)\leq |X|2^{-n}.
\end{equation}
Combining the above we obtain a lower bound:
\begin{equation}
  \abs*{X} \ge \f{3}{4}\gamma \cdot 2^n.
\end{equation}
Next we construct the set $S$. This is done through a sampling process on $X$. We take every $x \in X$, and independently randomly decide to include $x\in S$ with probability $2^np_{\psi}(x)$. We will now prove that $S$ satisfies the three properties of the theorem statement with non-zero probability. Note that the second property is automatically satisfied, since $S\subseteq X$. \\

The rest of the argument is probabilistic (over the random choice of $S$). We begin by calculating the expected size of $S$. It's easy to see that 
\begin{equation}
\E_S\lrb{\abs*{S}}=\sum_{x\in X}2^np_\psi\p{x}
  =2^n\PP_{x\sim p_\psi}\lrb{x\in X}=2^n\PP_{x\sim p_\psi}
  \lrb{2^np_\psi(x)\ge \f{\gamma}{4}}.
  \end{equation}
Furthermore, from \Cref{prop:property-ppsi} we know that 
  $\E_{x\sim q_\psi}\lrb{2^np_{\psi}(x)} \le \E_{x\sim p_\psi}\lrb{2^np_{\psi}(x)}$.
According to Markov's inequality, we have
\begin{equation}
  \gamma
    \le \E_{x\sim q_\psi}\lrb{2^np_{\psi}(x)}
    \le \E_{x\sim p_\psi}\lrb{2^np_{\psi}(x)}
    \le \PP_{x\sim p_\psi}\lrb{2^np_\psi(x)\geq \f{\gamma}{4}}+\f{\gamma}{4}.
\end{equation}
Therefore $\E_S\lrb{\abs*{S}}\ge \f{3}{4}\gamma \cdot 2^n$.
Next we compute the expected ``linearity" of $S$. In this argument we will need an upper bound on the size of $S$, which we will indirectly obtain from its expected size. Let $\lambda$ be a constant, which we will choose later, and define $A$ to be the event $\{\abs*{S} < \p{1+\lambda}\E_S\lrb{\abs*{S}}\}$.\\

\noindent Now we can compute the linearity. Define 
\begin{equation}
L(S)=\PP_{s,s'\in S}\lrb{s+s'\in S}.
\end{equation}
We calculate the expected linearity $\E_S\lrb{L(S)}$ as follows:
\begin{align}
  \E_S\lrb{L(S)} &= \E_S\lrb{\abs*{S}^{-2}\sum_{x,y\in S}\1[x+y\in S]} \\ 
    &= \E_S\lrb{\abs*{S}^{-2}\sum_{x,y\in X}\1[x\in S]\1[y\in S]\1[x+y\in S]} \\ 
    &\ge \E_S\lrb{\abs*{S}^{-2}\sum_{x,y\in X} 
      \1[x\in S]\1[y\in S]\1[x+y\in S] \1[A]} \\
    &\ge \f{2^{-2n}}{\p{1+\lambda}^2} 
      \E_S\lrb{\sum_{x,y\in X} \1[x\in S]\1[y\in S]\1[x+y\in S] \1[A]} \label{eq:S}
\end{align}
where the last inequality follows from $\abs*{S}\le \p{1+\lambda}\E_S\lrb{\abs*{S}}$
  and $\E_S\lrb{\abs*{S}}=2^n\PP_{x\sim p_\psi}\lrb{x\in X}\le 2^n$. We can continue this calculation:
\begin{align}
 &\f{2^{-2n}}{\p{1+\lambda}^2} 
      \E_S\lrb{\sum_{x,y\in X} \1[x\in S]\1[y\in S]\1[x+y\in S] \1[A]} \notag\\
    &\hspace{8em}= \f{2^{-2n}}{\p{1+\lambda}^2} \sum_{x,y\in X}
      \E_S\lrb{\1[x\in S]\1[y\in S]\1[x+y\in S]\1[A]}\\
    &\hspace{8em}\ge \f{2^{-2n}}{\p{1+\lambda}^2} \sum_{x,y\in X} \p{
      \E_S\lrb{\1[x\in S]\1[y\in S]\1[x+y\in S]} - \PP_S\lrb{\bar{A}} }\\
    &\hspace{8em}=  \f{2^{-2n}}{\p{1+\lambda}^2} \p{\sum_{x,y\in X}
        \E_S\lrb{\1[x\in S]\1[y\in S]\1[x+y\in S]}
        - \abs*{X}^2\PP_S\lrb{\bar{A}}\label{eq:last}
      }.
\end{align}
Let us now compute $\PP_S\lrb{\bar{A}}$.
From  Hoeffding's inequality, and the bounds 
  $\E_S\lrb{\abs*{S}}\ge \f{3}{4}\gamma \cdot 2^n$ and $\abs*{X}\le \f{4}{\gamma}2^n$,
  we have that
\begin{align}
  \PP_S\lrb{\bar{A}}
    = \PP_S\lrb{\abs{S} \ge \E_S\lrb{\abs*{S}} + \lambda \E_S\lrb{\abs*{S}}}
    \le \exp{-\f{2\lambda^2 \p{\E_S\lrb{\abs*{S}}}^2}{\abs*{X}}}
    &\le \exp{-\f{2\lambda^2 \f{9}{16}\gamma^2 \cdot 2^{2n}}{\f{4}{\gamma}2^n}} \\
    &= \exp{-9\lambda^2\gamma^3 2^{n-5}}.
\end{align}


Next we address the other term in \Cref{eq:last}:
\begin{align}
  \sum_{x,y\in X} \E_S\big[\1[x\in S]\1[y\in S]\1[x+y\in S]\big]
    &= \sum_{\substack{x,y\in X;\\ x+y\in X}}
      \E_S\big[\1[x\in S]\1[y\in S]\1[x+y\in S]\big] \\
    &\ge \sum_{\substack{x,y\in X;\\ x+y\in X}}2^{3n}p_\psi(x)p_\psi(y)p_\psi(x+y) \\
    &= 2^{2n} \sum_{\substack{x,y\in X;\\ x+y\in X}}2^{n}p_\psi(x)p_\psi(y)p_\psi(x+y).\label{eq:sumX}
\end{align}
To evaluate this last sum, we relate it to the related sum over $\mathbb{F}_2^{2n}$ (as opposed to $X$).  Note that we have 
\begin{equation}
\sum_{x,y\in \Fnn}2^n p_\psi(x)p_\psi(y)p_\psi(x+y)=\E_{x\sim q_{\psi}}\lrb{\abs*{\langle \psi|W_x|\psi\rangle}^2}\geq \gamma.
\end{equation}
Relating this sum to the summation in \Cref{eq:sumX} requires bounding three residual sums:
\begin{align}
  \sum_{x,y\in \Fnn; x\notin X} 2^n p_\psi(x)p_\psi(y)p_\psi(x+y) 
    &\le \f{\gamma}{4} \sum_{x,y\in \Fnn} p_\psi(y)p_\psi(x+y) = \f{\gamma}{4}, \\
  \sum_{x,y\in \Fnn; y\notin X} 2^n p_\psi(x)p_\psi(y)p_\psi(x+y) 
    &\le \f{\gamma}{4} \sum_{x,y\in \Fnn} p_\psi(x)p_\psi(x+y) = \f{\gamma}{4},\\
  \sum_{x,y\in \Fnn; x+y\notin X} 2^n p_\psi(x)p_\psi(y)p_\psi(x+y) 
    &\le \f{\gamma}{4} \sum_{x,y\in \Fnn} p_\psi(x)p_\psi(y) = \f{\gamma}{4},
\end{align}
Combining these and working out we obtain the lower bound:
\begin{equation}
  \E_S\lrb{L(S)} 
    \ge \f{1}{\p{1+\lambda}^2} \p{\gamma - \f{3}{4}\gamma - 
      2^{-2n}\abs*{X}^2e^{-9\lambda^2 \gamma^3 2^{n-5}}}
    \ge \f{1}{\p{1+\lambda}^2} \p{\f{1}{4}\gamma - 
      \f{16}{\gamma^2}e^{-9\lambda^2 \gamma^3 2^{n-5}}}.
\end{equation}
Fix $\lambda = 0.01$, for $n$ such that $2^n\ge \f{320000}{9}\cdot \f{3\ln\p{1/\gamma}+\ln 1600}{\gamma^3}
  = \f{C''\ln\p{C'''/\gamma}}{\gamma^3}$ with $C'$ and $C''$ some 
  constants, we have $\E_S\lrb{L(S)} \ge \f{\gamma}{5}$.
Using the Chernoff bound, Markov's inequality, and the union bound, we conclude that there exists $S$,
  such that $\abs*{S}\ge \f{\gamma}{2}\cdot 2^n$ and 
  $\PP_{s,s'\in S}\lrb{s+s'\in S}\geq \f{\gamma}{6}$.
\end{proof}
